t.script:
// ── Données initiales ──────────────────────────────────────
var _d = document.getElementById("pwa-init-data").dataset;
const SESSIONS = JSON.parse(_d.sessions || "[]");
const SELECTED = JSON.parse(_d.selected || "null");
const CSRF = _d.csrf || "";

// ── État ───────────────────────────────────────────────────
let currentSessionId = SELECTED ? SELECTED.id : null;
let scanning = false;
let stream = null;
let scanResolved = false;
let deferredInstallPrompt = null;

// ── Éléments DOM ───────────────────────────────────────────
const sessionSelect = document.getElementById("session-select");
const noSessionMsg  = document.getElementById("no-session-msg");
const statsRow      = document.getElementById("stats-row");
const statScanned   = document.getElementById("stat-scanned");
const statMissing   = document.getElementById("stat-missing");
const scanCard      = document.getElementById("scan-card");
const logCard       = document.getElementById("log-card");
const scanLog       = document.getElementById("scan-log");
const btnCamera     = document.getElementById("btn-camera");
const manualInput   = document.getElementById("manual-barcode");
const btnManual     = document.getElementById("btn-manual");
const overlay       = document.getElementById("camera-overlay");
const video         = document.getElementById("camera-video");
const cancelBtn     = document.getElementById("camera-cancel");
const toast         = document.getElementById("toast");
const installBanner = document.getElementById("install-banner");
const installBtn    = document.getElementById("install-btn");
const installDismiss= document.getElementById("install-dismiss");

// ── PWA Service Worker ─────────────────────────────────────
if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("/asset-inventory/scan/sw.js", {
        scope: "/asset-inventory/"
    }).catch(() => {});
}

// ── Bannière installation ──────────────────────────────────
window.addEventListener("beforeinstallprompt", (e) => {
    e.preventDefault();
    deferredInstallPrompt = e;
    installBanner.classList.add("show");
});
installBtn.onclick = async () => {
    if (!deferredInstallPrompt) return;
    deferredInstallPrompt.prompt();
    await deferredInstallPrompt.userChoice;
    deferredInstallPrompt = null;
    installBanner.classList.remove("show");
};
installDismiss.onclick = () => installBanner.classList.remove("show");

// ── Init sessions ──────────────────────────────────────────
function initSessions() {
    if (!SESSIONS || SESSIONS.length === 0) {
        noSessionMsg.style.display = "block";
        return;
    }
    sessionSelect.style.display = "block";
    sessionSelect.innerHTML = SESSIONS.map(s =>
        `<option value="${s.id}" ${s.id === currentSessionId ? "selected" : ""}>
            ${s.name} — ${s.date}
        </option>`
    ).join("");
    sessionSelect.onchange = () => {
        currentSessionId = parseInt(sessionSelect.value);
        refreshStats();
    };
    statsRow.style.display = "flex";
    scanCard.style.display = "block";
    if (SELECTED) {
        statScanned.textContent = SELECTED.scanned;
        statMissing.textContent = SELECTED.missing;
    }
}

// ── JSON-RPC helper ────────────────────────────────────────
async function rpc(model, method, args) {
    const resp = await fetch("/web/dataset/call_kw", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            id: Date.now(),
            params: {
                model,
                method,
                args,
                kwargs: { context: {} },
            },
        }),
    });
    const data = await resp.json();
    if (data.error) throw new Error(data.error.data?.message || data.error.message);
    return data.result;
}

// ── Rafraîchir les stats ───────────────────────────────────
async function refreshStats() {
    if (!currentSessionId) return;
    try {
        const [rec] = await rpc("asset.inventory", "read", [
            [currentSessionId],
            ["scanned_count", "missing_count"],
        ]);
        statScanned.textContent = rec.scanned_count;
        statMissing.textContent = rec.missing_count;
    } catch (_) {}
}

// ── Traiter un barcode ─────────────────────────────────────
async function processBarcode(barcode) {
    if (!barcode || !currentSessionId) return;
    barcode = barcode.trim();
    if (!barcode) return;
    try {
        const result = await rpc("asset.inventory", "action_scan_barcode", [
            [currentSessionId], barcode
        ]);
        let type, ico, msg;
        if (result.status === "found") {
            type = "found"; ico = "✅"; msg = result.name;
            showToast(`✓ ${result.name} ajouté`, "green");
            await refreshStats();
        } else if (result.status === "duplicate") {
            type = "duplicate"; ico = "⚠️"; msg = `Déjà scanné : ${result.name}`;
            showToast(`Déjà dans l'inventaire`, "orange");
        } else {
            type = "not_found"; ico = "❌"; msg = `Inconnu : ${result.barcode || barcode}`;
            showToast(`Actif non trouvé`, "red");
        }
        addLog(type, ico, msg, barcode);
    } catch (e) {
        showToast("Erreur : " + e.message, "red");
    }
}

// ── Journal des scans ──────────────────────────────────────
function addLog(type, ico, msg, barcode) {
    logCard.style.display = "block";
    const li = document.createElement("li");
    li.className = `log-item ${type}`;
    li.innerHTML = `<span class="ico">${ico}</span><span>${msg}<br><small style="opacity:.7">${barcode}</small></span>`;
    scanLog.prepend(li);
    // Garder les 20 derniers
    while (scanLog.children.length > 20) scanLog.lastChild.remove();
}

// ── Toast ──────────────────────────────────────────────────
let toastTimer;
function showToast(msg, color = "black") {
    toast.textContent = msg;
    toast.style.background = color === "green" ? "rgba(40,167,69,.9)"
        : color === "orange" ? "rgba(255,193,7,.9)"
        : color === "red" ? "rgba(220,53,69,.9)"
        : "rgba(0,0,0,.85)";
    if (color === "orange") toast.style.color = "#000";
    else toast.style.color = "#fff";
    toast.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove("show"), 2500);
}

// ── Caméra ─────────────────────────────────────────────────
btnCamera.onclick = openCamera;
cancelBtn.onclick = closeCamera;

// Chargement de @zxing/library (même version qu'Odoo — global window.ZXing)
let _zxingReader = null;
async function loadZXing() {
    if (_zxingReader) return _zxingReader;
    await new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = "https://cdn.jsdelivr.net/npm/@zxing/library@0.19.2/umd/index.min.js";
        s.onload = resolve;
        s.onerror = () => reject(new Error("Échec chargement ZXing CDN"));
        document.head.appendChild(s);
    });
    const ZXing = window.ZXing;
    if (!ZXing || !ZXing.MultiFormatReader) {
        throw new Error("ZXing non disponible après chargement");
    }
    // Même approche qu'Odoo : MultiFormatReader avec hints
    const hints = new Map([
        [ZXing.DecodeHintType.POSSIBLE_FORMATS, [
            ZXing.BarcodeFormat.CODE_128,
            ZXing.BarcodeFormat.CODE_39,
            ZXing.BarcodeFormat.CODE_93,
            ZXing.BarcodeFormat.EAN_13,
            ZXing.BarcodeFormat.EAN_8,
            ZXing.BarcodeFormat.UPC_A,
            ZXing.BarcodeFormat.UPC_E,
            ZXing.BarcodeFormat.QR_CODE,
            ZXing.BarcodeFormat.DATA_MATRIX,
            ZXing.BarcodeFormat.ITF,
        ]],
        [ZXing.DecodeHintType.TRY_HARDER, true],
    ]);
    const reader = new ZXing.MultiFormatReader();
    reader.setHints(hints);
    _zxingReader = { ZXing, reader };
    return _zxingReader;
}
// Précharger silencieusement dès ouverture de la page
loadZXing().catch(() => {});

async function openCamera() {
    if (!currentSessionId) { showToast("Aucune session sélectionnée", "red"); return; }
    if (!navigator.mediaDevices) {
        showToast("Caméra non disponible (HTTPS requis)", "red");
        return;
    }
    try {
        stream = await navigator.mediaDevices.getUserMedia({
            video: { facingMode: "environment", width: { ideal: 1280 }, height: { ideal: 720 } },
        });
    } catch (_) {
        showToast("Accès caméra refusé", "red");
        return;
    }
    video.srcObject = stream;
    stream.getTracks().forEach(t => { t.onended = () => { if (!scanResolved) closeCamera(); }; });
    overlay.classList.add("active");
    scanResolved = false;

    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");

    if ("BarcodeDetector" in window) {
        // ── Natif Chrome/Edge Android ──────────────────────
        const detector = new window.BarcodeDetector({
            formats: ["code_128","code_39","code_93","ean_13","ean_8","upc_a","upc_e","qr_code"],
        });
        async function tick() {
            if (scanResolved) return;
            if (video.readyState >= 2 && video.videoWidth > 0) {
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                ctx.drawImage(video, 0, 0);
                try {
                    const codes = await detector.detect(canvas);
                    if (codes.length > 0) {
                        closeCamera();
                        await processBarcode(codes[0].rawValue);
                        return;
                    }
                } catch (_) {}
            }
            setTimeout(tick, 150);
        }
        setTimeout(tick, 1000);
    } else {
        // ── Fallback ZXing — même approche qu'Odoo ─────────
        // API bas niveau : MultiFormatReader.decode(binaryBitmap)
        // Stateless : aucun état interne à nettoyer entre sessions
        try {
            const { ZXing, reader } = await loadZXing();
            async function tickZXing() {
                if (scanResolved) return;
                if (video.readyState >= 2 && video.videoWidth > 0) {
                    canvas.width = video.videoWidth;
                    canvas.height = video.videoHeight;
                    ctx.drawImage(video, 0, 0);
                    try {
                        const lum = new ZXing.HTMLCanvasElementLuminanceSource(canvas);
                        const bmp = new ZXing.BinaryBitmap(new ZXing.HybridBinarizer(lum));
                        const result = reader.decode(bmp);
                        if (result) {
                            closeCamera();
                            await processBarcode(result.getText());
                            return;
                        }
                    } catch (err) {
                        // NotFoundException = normal (pas de code dans ce frame)
                        if (err && err.name !== "NotFoundException") {
                            console.warn("ZXing decode error:", err);
                        }
                    }
                }
                setTimeout(tickZXing, 150);
            }
            setTimeout(tickZXing, 1000);
        } catch (err) {
            closeCamera();
            showToast("Erreur scanner : " + (err && err.message ? err.message : String(err)), "red");
        }
    }
}

function closeCamera() {
    scanResolved = true;
    if (stream) { stream.getTracks().forEach(t => t.stop()); stream = null; }
    video.srcObject = null;
    overlay.classList.remove("active");
}

// ── Saisie manuelle ────────────────────────────────────────
btnManual.onclick = () => {
    const val = manualInput.value.trim();
    if (val) { manualInput.value = ""; processBarcode(val); }
};
manualInput.onkeydown = (e) => {
    if (e.key === "Enter") { btnManual.click(); e.preventDefault(); }
};

// ── Douchette USB/Bluetooth (saisie rapide) ───────────────
let barcodeBuffer = "";
let barcodeTimer;
document.addEventListener("keypress", (e) => {
    if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
    clearTimeout(barcodeTimer);
    barcodeBuffer += e.key;
    barcodeTimer = setTimeout(() => {
        if (barcodeBuffer.length >= 4) processBarcode(barcodeBuffer);
        barcodeBuffer = "";
    }, 80);
});

// ── Lancement ─────────────────────────────────────────────
initSessions();
